/** Retain only ephemeral keys generated by the existing actual funding fixture.
 * No production key, actor rebinding or hand-written creation receipt is used. */
import {Keypair} from '@solana/web3.js';
import {vi} from 'vitest';
import {charterSalesFixture} from './charterSales';
